struct Point {
    x: i32,
    y: i32,
}

fn classify(point: &Point) -> &'static str {
    match (point.x, point.y) {
        (0, 0) => "origin",
        (0, _) => "on the y axis",
        (_, 0) => "on the x axis",
        (x, y) if x == y => "diagonal",
        _ => "somewhere else",
    }
}

fn main() {
    let point = Point { x: 2, y: 2 };
    let Point { x, y } = &point;
    println!("{x} {y}");

    let Some(label) = Some(classify(&point)) else {
        return;
    };
    println!("{label}");

    let mut stack = vec![1, 2, 3];
    while let Some(top) = stack.pop() {
        println!("{top}");
    }
}

