fn largest<T: PartialOrd + Copy>(items: &[T]) -> T {
    let mut max = items[0];          // panics on an empty slice
    for &item in items {
        if item > max {
            max = item;
        }
    }
    max
}

fn main() {
    println!("{}", largest(&[3, 9, 2]));
    println!("{}", largest(&['a', 'z', 'm']));
}

