    let joined: Vec<String> = words
        .iter()
        .copied()
        .zip(1..)
        .map(|(word, number)| format!("{number}-{word}"))
        .collect();

    let short: Vec<&str> = words.iter().copied().filter(|word| word.len() <= 4).collect();
    // rev() needs a double-ended source, so reverse before filter
    let top: Vec<i32> = (1..=100).rev().filter(|n| n % 3 == 0).take(4).collect();

