use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum ConfigError {
    Missing,
    Invalid(ParseIntError),
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::Missing => write!(f, "port is missing"),
            ConfigError::Invalid(error) => write!(f, "invalid port: {error}"),
        }
    }
}

impl std::error::Error for ConfigError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            ConfigError::Invalid(error) => Some(error),
            ConfigError::Missing => None,
        }
    }
}

fn parse_port(text: &str) -> Result<u16, ConfigError> {
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return Err(ConfigError::Missing);
    }
    trimmed.parse().map_err(ConfigError::Invalid)
}

fn main() {
    println!("{:?}", parse_port("8080"));
    println!("{}", parse_port("abc").unwrap_err());
}

