fn main() {
    // E0382: use after move — borrow instead of moving again
    let name = String::from("Felipe");
    let moved = name;
    let borrowed = &moved;
    println!("{borrowed}");

    // E0502: overlapping borrows — let the shared borrow end first
    let mut text = String::from("hi");
    {
        let shared = &text;
        println!("{shared}");
    }
    let exclusive = &mut text;
    exclusive.push('!');
    println!("{exclusive}");
}
